import re

def check(output, reference, input) -> tuple[float, str]:
    try:
        # Normalize reference
        if isinstance(reference, str):
            ref_label = reference.strip().lower()
        else:
            # Fallback for non-string reference (e.g., parsed JSON)
            ref_label = str(reference).strip().lower()

        # Normalize output: strip whitespace, code fences, trailing punctuation, lowercase
        out_str = str(output).strip()
        # Remove markdown code fences
        out_str = re.sub(r'^```[\w]*\n?', '', out_str)
        out_str = re.sub(r'\n?```$', '', out_str)
        out_str = out_str.strip()
        # Remove trailing punctuation (.,!?;:)
        out_str = re.sub(r'[.,!?;:]+$', '', out_str)
        out_label = out_str.lower()

        allowed = {'spam', 'ham'}

        # Check if reference is valid (should be, but defensive)
        if ref_label not in allowed:
            return 0.0, f"Invalid reference label: {ref_label}"

        # Check if output is exactly one of the allowed labels
        if out_label in allowed:
            if out_label == ref_label:
                return 1.0, "Correct label"
            else:
                return 0.0, f"Wrong label: expected {ref_label}, got {out_label}"
        else:
            return 0.0, f"Output not a valid label: '{out_str}' (normalized: '{out_label}')"

    except Exception as e:
        return 0.0, f"Grader error: {e}"

